    const presence = useTodayPresence(businessId, client.chatId, access.userId, features?.collaboration === true, access.role !== 'observer' && canOperateCustomer(access, client, 'sales.write') && data.capabilities?.includes('sales.write') === true, data.dialogueRevision);
    const others = presence.data?.participants.filter(row => row.userId !== access.userId && Date.parse(row.expiresAt) > Date.now()) || [];
    const dialogueChanged = features?.collaboration && presence.data && presence.data.dialogueRevision !== data.dialogueRevision;
    const briefSummary=data.memory.summary || data.callBrief?.lastSummary || data.calls[0]?.summary;
    const briefDate=data.memory.summary ? data.memory.sourceUpdatedAt : data.calls[0]?.timestamp;
