    const snapshotAccess = { ...access, can: (cap: string) => access.can(cap) || Boolean(access.checking && access.membership?.capabilities?.includes(cap)) };
    const showWrite = canOperateCustomer(snapshotAccess, client, 'sales.write') && data.capabilities?.includes('sales.write') === true;
    const showSend = canOperateCustomer(snapshotAccess, client, 'messages.send') && data.capabilities?.includes('messages.send') === true;
    const canWrite = canWritePermission && !loading && !error;
    const canSend = canOperateCustomer(access, client, 'messages.send') && data.capabilities?.includes('messages.send') === true;
